import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * The {@code readFrom} method now creates a fresh {@link Parser} instance for each
 * request and configures its {@link ParserOptions} **before** parsing.  This removes
 * the previous synchronized block that attempted to modify shared parser options,
 * which could be ineffective in a multi‑threaded environment and left the parser
 * vulnerable to XML External Entity (XXE) attacks.
 *
 * By disabling entity resolution ( {@code setResolveEntities(false)} ) on a
 * per‑call {@link ParserOptions} object and passing those options directly to
 * {@link Parser#parse(InputStream, ParserOptions)}, we guarantee that no external
 * entities are expanded, regardless of how the underlying parser implementation
 * reuses internal objects.  The method also closes the supplied {@link InputStream}
 * in a {@code finally} block to avoid resource leaks.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // other methods ...

    @Override
    public T readFrom(Class<T> clazz,
                      Type genericType,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Create a fresh parser for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Configure parser options securely before parsing.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disable external entity resolution to mitigate XXE.
        options.setResolveEntities(false);
        // (Optional) If the library version supports it, also disable DTD processing.
        // options.setSupportDTD(false);

        Document<T> document;
        try {
            // Parse using the securely configured options.
            document = parser.parse(entityStream, options);
        } finally {
            // Ensure the InputStream is closed to prevent resource leaks.
            try {
                entityStream.close();
            } catch (IOException ignored) {
                // Logging can be added here if desired.
            }
        }

        return document.getRoot();
    }

    // other methods ...
}
