 * sized regex string for every execution path.
 */
public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = LoggerFactory.getLogger(URLValidator.class);

    /** A safe, reasonably sized default URL regular expression. */
    private static final String DEFAULT_URL_REGEX =
            "^(https?|ftp)://[\\w.-]+(?:\\.[\\w.-]+)+(?:\\:\\d+)?(?:/[^\\s]*)?$";

    private String urlRegex;
    private String urlRegexExpression;

    // other methods ...

    /**
     * Returns a regular expression that can be used for client‑side URL validation.
     * <p>
     * The method follows a defensive strategy:
     * <ul>
     *   <li>If {@code urlRegexExpression} is provided, it is parsed and returned.
     *       Any parsing exception is logged and the method falls back to the safe default.</li>
     *   <li>If {@code urlRegexExpression} is absent but {@code urlRegex} is supplied,
     *       that value is returned.</li>
     *   <li>When neither field contains a usable value, a predefined, compact
     *       regular expression is returned.</li>
     * </ul>
     *
     * @return a non‑null regular expression string for URL validation
     */
    public String getUrlRegex() {
        // 1. Prefer the expression supplied by the user (may contain EL placeholders)
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                // parse may throw an exception – guard against it
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String && StringUtils.isNotBlank((String) parsed)) {
                    return (String) parsed;
                } else {
                    LOG.warn("Parsed urlRegexExpression is not a non‑empty String; falling back to default regex.");
                }
            } catch (Exception e) {
                // Parsing failed – log and continue to fallback
                LOG.warn("Failed to parse urlRegexExpression '{}': {}", urlRegexExpression, e.toString());
            }
        }

        // 2. Use the plain regex if it is defined and non‑empty
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex;
        }

        // 3. Final fallback – a safe, compact default regex
