static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Strip query parameters
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Remove any path information, keep only the file name
    String baseName = new File(name).getName();

    // Guard against empty after sanitization
    if (baseName.isEmpty()) {
        throw new IllegalArgumentException("File name is empty after sanitization");
    }

    // Build initial file
    File file = new File(dir, baseName);

    // Ensure the resulting file resides within the intended directory
    try {
        String canonicalDir = dir.getCanonicalPath();
        String canonicalFile = file.getCanonicalPath();
        if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
            // If the file is outside the target directory, reject
            throw new IllegalArgumentException("Invalid file name resulting in path traversal");
        }
    } catch (IOException e) {
        throw new IllegalStateException("Failed to resolve canonical paths", e);
    }

    // Determine prefix and suffix for duplicate handling
    int dot = baseName.lastIndexOf('.');
    String prefix = dot < 0 ? baseName : baseName.substring(0, dot);
    String suffix = dot < 0 ? "" : baseName.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}
