import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;
import org.springframework.util.FileCopyUtils;

/**
 * FactoryBean that creates a {@link SecureRandom} instance.
 *
 * <p>The previous implementation allowed an external {@link Resource} to be used as a
 * seed for the {@code SecureRandom} instance via {@code setSeed(byte[])}.  Supplying a
 * predictable or attacker‑controlled seed weakens the randomness and can lead to
 * cryptographic compromise.  This patched version removes that behaviour and relies
 * exclusively on the built‑in, platform‑provided seeding mechanism, which gathers
 * entropy from the operating system.</p>
 *
 * <p>If a seed {@link Resource} is configured, it is read and discarded solely to
 * avoid resource leaks; the data is never used to influence the RNG state.  A
 * warning could be logged here in a real application.</p>
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    /** Preferred algorithm – retained for compatibility but not used for seeding. */
    private String algorithm = "SHA1PRNG";

    /** Optional external seed resource – ignored for security reasons. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = createSecureRandomInstance();

        // Consume the seed resource if it was supplied, but do NOT use it for seeding.
        // This prevents resource leaks while ensuring the data cannot affect RNG state.
        if (seed != null) {
            try (InputStream is = seed.getInputStream()) {
                // Read and discard – the data is intentionally ignored.
                // Using FileCopyUtils ensures the stream is fully consumed.
                FileCopyUtils.copyToByteArray(is);
            } catch (IOException ignored) {
                // In production you might log this event; we deliberately ignore it
                // to keep the factory robust and not expose the seed data.
