        // Each call returns a freshly‑initialized SecureRandom instance.
        return false;
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link SecureRandom} instance using the strongest available algorithm.
     * Falls back to the default constructor if {@code SecureRandom.getInstanceStrong()}
     * is not supported on the current platform.
     *
     * @return a securely seeded {@code SecureRandom}
