public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // -----------------------------------------------------------------------
    //  Token validation according to RFC 6838 (media type) / RFC 7230
    // -----------------------------------------------------------------------
    //  token = 1*tchar
    //  tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*"
    //        / "+" / "-" / "." / "^" / "_" / "`" / "|" / "~"
    //        / DIGIT / ALPHA
    //  (i.e. any visible ASCII character except CTLs or the separators)
    //  separators = "()" "<>" "@" "," ";" ":" "\\" "\""
    //               "/" "[" "]" "?" "=" "{" "}" SP HTAB
    // -----------------------------------------------------------------------

    /** Lookup table: true = allowed token character, false = prohibited */
    private static final boolean[] TOKEN_CHAR = new boolean[128];

    static {
        // Initialise all printable ASCII characters (33‑126) as allowed.
        for (int i = 33; i <= 126; i++) {
            TOKEN_CHAR[i] = true;
        }
        // Explicitly mark the separator characters as prohibited.
        char[] separators = {
                '(', ')', '<', '>', '@', ',', ';', ':', '\\', '\"',
                '/', '[', ']', '?', '=', '{', '}', ' ', '\t'
        };
        for (char sep : separators) {
            TOKEN_CHAR[sep] = false;
        }
