/**
 * Normalizes a URI path.
 *
 * <p>This method guarantees that the returned path starts with a single leading slash.
 * It removes any superfluous leading slashes and, if the original path lacked a leading
 * slash, it prepends one.  An empty or {@code null} input is handled gracefully:
 * <ul>
 *   <li>{@code null} → {@code null}</li>
 *   <li>empty string → {@code "/"}</li>
 * </ul>
 *
 * @param path the raw path component, may be {@code null}
 * @return a normalized path suitable for use in {@link java.net.URI} construction,
 *         or {@code null} if the input was {@code null}
 */
private static String normalizePath(final String path) {
    if (path == null) {
        return null;
    }

    // Preserve the original string for later use
    String normalized = path;

    // Count leading slashes
    int leadingSlashCount = 0;
    while (leadingSlashCount < normalized.length()
            && normalized.charAt(leadingSlashCount) == '/') {
        leadingSlashCount++;
    }

    if (leadingSlashCount == 0) {
        // No leading slash – prepend one to avoid URI mis‑interpretation
        normalized = "/" + normalized;
    } else if (leadingSlashCount > 1) {
        // More than one leading slash – collapse to a single slash
        normalized = normalized.substring(leadingSlashCount - 1);
    }
    // If leadingSlashCount == 1 we keep the path unchanged

    // Ensure that an empty string becomes "/"
    if (normalized.isEmpty()) {
        normalized = "/";
    }

    return normalized;
}
