     *                     malformed
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        if (in == null) {
            throw new IllegalArgumentException("InputStream must not be null");
        }
        if (out == null) {
            throw new IllegalArgumentException("Output buffer must not be null");
        }

        int position = 0;
        final int total = out.length;

        // Guard against pathological inputs – we never need more than
        // total iterations of writing bytes, but a malformed stream could
        // cause many more reads. The loop will stop as soon as the output
        // buffer is filled or an error is detected.
        while (position < total) {
            final int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of compressed stream");
            }

            // n must be in the range 0‑255; values outside this range are impossible
