     * @param v the raw value read (must fit in {@code t} bits)
     * @param t the number of bits that were read (must be in the range 1‑31)
     * @return the sign‑extended integer value
     * @throws IllegalArgumentException if {@code t} is out of range or {@code v}
     *         does not fit in {@code t} bits
     */
    private int extend(int v, final int t) {
        // ----- input validation -------------------------------------------------
        if (t < 1 || t > 31) {
            throw new IllegalArgumentException("Bit length 't' must be between 1 and 31 inclusive.");
        }

        // The maximum unsigned value that can be represented with t bits.
        int maxUnsigned = (1 << t) - 1;
        if (v < 0 || v > maxUnsigned) {
            throw new IllegalArgumentException(
                "Value 'v' (" + v + ") does not fit in the supplied bit length t=" + t);
        }

        // ----- sign extension (single conditional, no loop) --------------------
        int vt = 1 << (t - 1);               // 2^(t‑1)
        if (v < vt) {                        // if the sign bit is 0, adjust to negative
            v += (-1 << t) + 1;              // equivalent to v - (1 << t)
        }
        return v;
    }
