 * with the supplied {@code principal} and {@code credentials}.  The method
 * validates the inputs, negotiates TLS, sets the authentication environment,
 * forces a bind (via an empty lookup) and closes all resources on failure.
 *
 * @param ldapContextFactory the factory that provides LDAP connection settings
 * @param principal the DN or user name to bind as
 * @param credentials the password for {@code principal}
 * @return a fully authenticated {@link LdapContext}
 * @throws NamingException if the bind or any LDAP operation fails
 */
private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                Object principal,
                                                Object credentials) throws NamingException {
    // ---- Input validation ----------------------------------------------------
    if (principal == null || principal.toString().trim().isEmpty()) {
        throw new IllegalArgumentException("Principal must not be null or empty");
    }
    if (credentials == null || credentials.toString().trim().isEmpty()) {
        throw new IllegalArgumentException("Credentials must not be null or empty");
    }

    // ---- Build the initial environment (without authentication) ------------
    JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiFactory.getUrl());

    LdapContext ctx = null;
    StartTlsResponse tls = null;
    boolean authenticated = false; // tracks successful bind

    try {
        // 1. Create the context (no credentials yet)
        ctx = new InitialLdapContext(env, null);

        // 2. Upgrade the connection to TLS
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate();

        // 3. Supply authentication information *after* TLS is established
        ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                jndiFactory.getAuthenticationMechanism());
        ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
        ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

        // 4. Force a bind to verify the supplied credentials.
        // An empty lookup triggers the bind without retrieving any data.
        ctx.lookup("");

        // If we reach here the bind succeeded.
        authenticated = true;
