        // TLS negotiation failed
        securityLog.error(withRealm("Failed to negotiate TLS with '%s': %s",
                server(jndiFactory), e.getMessage()), e);
        throw new CommunicationException(e.getMessage(), e);
    } catch (NamingException e) {
        // LDAP bind or other LDAP error
        securityLog.error(withRealm("LDAP authentication failed for user '%s' on server '%s': %s",
                principal, server(jndiFactory), e.getMessage()), e);
        throw e;
    } finally {
        // Close the TLS channel if it was opened
        if (tls != null) {
            try {
                tls.close();
            } catch (IOException ignored) {
                // Ignored – already logged if TLS negotiation failed
            }
