        // Reject absolute paths
        if (entryName.startsWith("/") || entryName.startsWith("\\") || entryName.matches("^[a-zA-Z]:.*")) {
            throw new IOException("Invalid entry name: " + entryName);
        }
        // Resolve and normalize the path within the target directory
        Path entryPath = targetDirPath.resolve(entryName).normalize();

        // Ensure the normalized path is still inside the target directory
        if (!entryPath.startsWith(targetDirPath)) {
            throw new IOException("Entry " + entryName + " would be extracted outside of target directory");
