public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Secure XML parsing helpers
    // -------------------------------------------------------------------------

    /**
     * Parses the supplied {@link InputSource} into a {@link Document} using a
     * {@link DocumentBuilderFactory} that has all known XXE‑related features
     * disabled.
     *
     * @param source the XML source to parse
     * @return a DOM {@link Document}
     * @throws Exception if a parsing error occurs
     */
    private Document secureParse(InputSource source) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // ---- Secure configuration (XXE mitigation) -------------------------
        // Disallow DOCTYPE declarations
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disallow external general entities
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // Disallow external parameter entities
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Enable secure processing
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Prevent access to external DTDs / Schemas
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        // Preserve namespace awareness as required by XPath processing
        dbf.setNamespaceAware(true);
        // ---------------------------------------------------------------------

        DocumentBuilder builder = dbf.newDocumentBuilder();
        return builder.parse(source);
    }

    // -------------------------------------------------------------------------
    // Original logic with security enhancements
    // -------------------------------------------------------------------------

    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;

        // 1. Try Camel type conversion first (kept unchanged)
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e;
            }
        }

        // 2. Fallback handling – now using secure XML parsing for String / InputStream
        if (answer == null) {
            if (body instanceof WrappedFile) {
                // Convert the wrapped file to an InputStream and parse securely
                InputStream is = exchange.getContext().getTypeConverter()
                        .convertTo(InputStream.class, exchange, body);
                if (is != null) {
                    answer = secureParse(new InputSource(is));
                }
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext().getTypeConverter()
                        .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                // Parse the XML string securely
                answer = secureParse(new InputSource(new StringReader((String) body)));
            } else if (body instanceof InputStream) {
                // Direct InputStream handling (not originally covered)
                answer = secureParse(new InputSource((InputStream) body));
            }
        }

        // 3. If no specific document type is required and we still have no answer,
        //    fall back to the original body.
        if (type == null && answer == null) {
            answer = body;
        } else if (answer == null) {
            // Propagate the original conversion exception or throw a clear one.
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods (unchanged)
}
