    /**
     * Compare {@code fromVersion} and {@code toVersion}.
     *
     * <p>The method now validates its inputs and handles malformed version strings
     * safely. It expects a version in the form {@code "x.y.z"} where {@code x},
     * {@code y} and {@code z} are integer numbers. If the input does not meet this
     * contract an {@link IllegalArgumentException} is thrown with a clear
     * message, preventing {@link ArrayIndexOutOfBoundsException} or
     * {@link NumberFormatException} from bubbling up and causing a denial‑of‑service.</p>
     *
     * @param fromVersion the initial version, must not be {@code null}
     * @param toVersion   the end version, must not be {@code null}
     * @return a negative integer, zero, or a positive integer as {@code fromVersion}
     *         is less than, equal to, or greater than {@code toVersion}
     * @throws IllegalArgumentException if either argument is {@code null},
     *                                  does not contain exactly three components,
     *                                  or contains non‑numeric components
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        if (fromVersion == null || toVersion == null) {
            throw new IllegalArgumentException("Version strings must not be null");
        }

        String[] fromArr = splitVersion(fromVersion);
        String[] toArr   = splitVersion(toVersion);

        // Compare each component (major, minor, patch) in order.
        for (int i = 0; i < 3; i++) {
            int fromPart = parsePart(fromArr[i]);
            int toPart   = parsePart(toArr[i]);

            int cmp = Integer.compare(fromPart, toPart);
            if (cmp != 0) {
                return cmp;               // first non‑equal component determines the result
            }
        }
        return 0;   // all three components are equal
    }

    /** Splits a version string and validates that it has exactly three dot‑separated parts. */
    private static String[] splitVersion(String version) {
        String[] parts = version.trim().split("\\.");
        if (parts.length != 3) {
            throw new IllegalArgumentException(
                "Version must consist of three numeric components separated by '.' : " + version);
        }
        return parts;
    }

    /** Parses a single version component, guaranteeing a numeric value. */
    private static int parsePart(String part) {
        try {
            return Integer.parseInt(part);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException(
                "Version component is not a valid integer: '" + part + "'", e);
        }
    }

